package config

import (
	"fmt"
	"os"
	"strconv"
)

// Config 全局配置，所有项均可由环境变量覆盖，默认值对接本地开发环境。
type Config struct {
	ServerPort   string
	DBHost       string
	DBPort       string
	DBUser       string
	DBPassword   string
	DBName       string
	JWTSecret    string
	InitialCoins int // 注册即赠送的初始记忆硬币
	UploadDir    string
}

func getenv(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

func getenvInt(key string, fallback int) int {
	if v := os.Getenv(key); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			return n
		}
	}
	return fallback
}

// Load 读取配置。
func Load() *Config {
	return &Config{
		ServerPort:   getenv("SERVER_PORT", "8080"),
		DBHost:       getenv("DB_HOST", "192.168.5.100"),
		DBPort:       getenv("DB_PORT", "3306"),
		DBUser:       getenv("DB_USER", "root"),
		DBPassword:   getenv("DB_PASSWORD", "123456"),
		DBName:       getenv("DB_NAME", "memory_link"),
		JWTSecret:    getenv("JWT_SECRET", "memory-link-secret-change-me"),
		InitialCoins: getenvInt("INITIAL_COINS", 100),
		UploadDir:    getenv("UPLOAD_DIR", "uploads"),
	}
}

// dsn 拼装 MySQL DSN；withDB=false 时不指定库名（用于建库前连接）。
func (c *Config) dsn(withDB bool) string {
	dbName := ""
	if withDB {
		dbName = c.DBName
	}
	return fmt.Sprintf("%s:%s@tcp(%s:%s)/%s?charset=utf8mb4&parseTime=True&loc=Local",
		c.DBUser, c.DBPassword, c.DBHost, c.DBPort, dbName)
}

// DSN 带库名的连接串。
func (c *Config) DSN() string { return c.dsn(true) }

// RootDSN 不带库名的连接串，用于首次建库。
func (c *Config) RootDSN() string { return c.dsn(false) }

package model

import (
	"database/sql/driver"
	"encoding/json"
	"errors"
	"time"
)

// StringSlice 以 JSON 文本形式存于单个字段中的字符串切片（用于照片 URL 列表）。
type StringSlice []string

func (s StringSlice) Value() (driver.Value, error) {
	if s == nil {
		return "[]", nil
	}
	b, err := json.Marshal(s)
	return string(b), err
}

func (s *StringSlice) Scan(input interface{}) error {
	var data []byte
	switch v := input.(type) {
	case []byte:
		data = v
	case string:
		data = []byte(v)
	case nil:
		*s = StringSlice{}
		return nil
	default:
		return errors.New("StringSlice: unsupported scan type")
	}
	if len(data) == 0 {
		*s = StringSlice{}
		return nil
	}
	return json.Unmarshal(data, s)
}

// User 用户表。
type User struct {
	ID           uint      `gorm:"primaryKey" json:"id"`
	Username     string    `gorm:"size:50;uniqueIndex;not null" json:"username"`
	PasswordHash string    `gorm:"size:255;not null" json:"-"`
	Nickname     string    `gorm:"size:50" json:"nickname"`
	Avatar       string    `gorm:"size:500" json:"avatar"`
	CoinBalance  int       `gorm:"not null;default:0" json:"coinBalance"` // 可用记忆硬币余额
	CreatedAt    time.Time `json:"createdAt"`
}

// 故事状态。
const (
	StoryOpen      = "open"      // 求看中（可被回应/采纳）
	StoryCompleted = "completed" // 已采纳结算
)

// Story 故事表（一条“求看”需求 = 一张双面明信片的“过去”那一面）。
// Reward 是发帖时从发起人余额冻结、托管在故事上的悬赏硬币。
type Story struct {
	ID                 uint        `gorm:"primaryKey" json:"id"`
	UserID             uint        `gorm:"index;not null" json:"userId"`
	Title              string      `gorm:"size:100;not null" json:"title"`
	Location           string      `gorm:"size:100" json:"location"`
	MemoryText         string      `gorm:"type:text" json:"memoryText"`     // 过去回忆
	OldPhotos          StringSlice `gorm:"type:text" json:"oldPhotos"`      // 老照片 URL 列表
	Reward             int         `gorm:"not null;default:0" json:"reward"` // 托管中的悬赏硬币
	Status             string      `gorm:"size:20;index;not null;default:open" json:"status"`
	AcceptedResponseID *uint       `gorm:"index" json:"acceptedResponseId,omitempty"` // 被采纳的回应
	CreatedAt          time.Time   `json:"createdAt"`
	UpdatedAt          time.Time   `json:"updatedAt"`
}

// Response 回应表（一次“替他去拍” = 双面明信片的“当下”那一面）。
type Response struct {
	ID        uint      `gorm:"primaryKey" json:"id"`
	StoryID   uint      `gorm:"index;not null" json:"storyId"`
	UserID    uint      `gorm:"index;not null" json:"userId"`
	NewPhoto  string    `gorm:"size:500" json:"newPhoto"` // 当下现场新照
	Message   string    `gorm:"type:text" json:"message"` // 给发起人的寄语
	CreatedAt time.Time `json:"createdAt"`
}

// 硬币流水类型。
const (
	TxRegisterGift = "register_gift"  // 注册赠送：+
	TxFreeze       = "freeze"         // 发帖冻结悬赏：-
	TxAppendFreeze = "append_freeze"  // 追加悬赏冻结：-
	TxRewardIncome = "reward_income"  // 被采纳获得悬赏：+
	TxRefund       = "refund"         // 解冻退回：+（预留）
)

// CoinTransaction 硬币流水表，一条记录对应某用户一次余额变动。
type CoinTransaction struct {
	ID              uint      `gorm:"primaryKey" json:"id"`
	UserID          uint      `gorm:"index;not null" json:"userId"`
	Type            string    `gorm:"size:30;not null" json:"type"`
	Amount          int       `gorm:"not null" json:"amount"` // 带符号：正入账、负出账
	BalanceAfter    int       `gorm:"not null" json:"balanceAfter"`
	RelatedStoryID  *uint     `gorm:"index" json:"relatedStoryId,omitempty"`
	Remark          string    `gorm:"size:200" json:"remark"`
	CreatedAt       time.Time `json:"createdAt"`
}

package db

import (
	"fmt"
	"log"
	"time"

	"memorylink/internal/config"
	"memorylink/internal/model"

	"gorm.io/driver/mysql"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// DB 全局数据库句柄。
var DB *gorm.DB

// Init 建库（如不存在）、连接并执行表结构迁移。
func Init(cfg *config.Config) {
	// 1) 不指定库名连接，确保数据库存在。
	root, err := gorm.Open(mysql.Open(cfg.RootDSN()), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Warn),
	})
	if err != nil {
		log.Fatalf("连接 MySQL 失败: %v", err)
	}
	createSQL := fmt.Sprintf(
		"CREATE DATABASE IF NOT EXISTS `%s` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci",
		cfg.DBName)
	if err := root.Exec(createSQL).Error; err != nil {
		log.Fatalf("创建数据库失败: %v", err)
	}
	if sqlDB, err := root.DB(); err == nil {
		_ = sqlDB.Close()
	}

	// 2) 连接目标库。
	gormDB, err := gorm.Open(mysql.Open(cfg.DSN()), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Warn),
	})
	if err != nil {
		log.Fatalf("打开数据库 %s 失败: %v", cfg.DBName, err)
	}
	sqlDB, err := gormDB.DB()
	if err != nil {
		log.Fatalf("获取 sql.DB 失败: %v", err)
	}
	sqlDB.SetMaxOpenConns(50)
	sqlDB.SetMaxIdleConns(10)
	sqlDB.SetConnMaxLifetime(time.Hour)

	if err := gormDB.AutoMigrate(
		&model.User{},
		&model.Story{},
		&model.Response{},
		&model.CoinTransaction{},
	); err != nil {
		log.Fatalf("数据库迁移失败: %v", err)
	}

	DB = gormDB
	log.Printf("数据库 %s 初始化完成", cfg.DBName)
}

