package utils

import "github.com/gin-gonic/gin"

// 统一响应结构：{ code, msg, data }。code=0 表示成功。
type apiResp struct {
	Code int         `json:"code"`
	Msg  string      `json:"msg"`
	Data interface{} `json:"data,omitempty"`
}

func OK(c *gin.Context, data interface{}) {
	c.JSON(200, apiResp{Code: 0, Msg: "ok", Data: data})
}

func Fail(c *gin.Context, httpCode int, msg string) {
	c.JSON(httpCode, apiResp{Code: httpCode, Msg: msg})
}

package utils

import "golang.org/x/crypto/bcrypt"

// HashPassword 使用 bcrypt 加密密码。
func HashPassword(pwd string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pwd), bcrypt.DefaultCost)
	return string(b), err
}

// CheckPassword 校验明文密码与哈希是否匹配。
func CheckPassword(hash, pwd string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pwd)) == nil
}

package middleware

import (
	"net/http"
	"strings"

	"memorylink/internal/config"
	"memorylink/internal/utils"

	"github.com/gin-gonic/gin"
)

// Auth 校验 JWT，将 userId 注入上下文。
func Auth(cfg *config.Config) gin.HandlerFunc {
	return func(c *gin.Context) {
		token := strings.TrimSpace(utils.ExtractToken(c))
		if token == "" {
			utils.Fail(c, http.StatusUnauthorized, "未登录")
			c.Abort()
			return
		}
		claims, err := utils.ParseToken(cfg.JWTSecret, token)
		if err != nil {
			utils.Fail(c, http.StatusUnauthorized, "登录已失效，请重新登录")
			c.Abort()
			return
		}
		c.Set(utils.CtxUserID, claims.UserID)
		c.Next()
	}
}

