	"path/filepath"
	"strconv"
	"time"

	"memorylink/internal/utils"

	"github.com/gin-gonic/gin"
)

// Upload 接收单张图片，存入 uploads/yyyy-mm/ 并返回可访问 URL。
func Upload(c *gin.Context) {
	file, err := c.FormFile("file")
	if err != nil {
		utils.Fail(c, http.StatusBadRequest, "请选择要上传的图片")
		return
	}

	// 限制 10MB。
