package router

import (
	"memorylink/internal/config"
	"memorylink/internal/handler"
	"memorylink/internal/middleware"

	"github.com/gin-gonic/gin"
	"gorm.io/gorm"
)

// Setup 装配所有路由与依赖。
func Setup(db *gorm.DB, cfg *config.Config) *gin.Engine {
	r := gin.Default()

	// 静态资源：上传的图片。
	r.Static("/uploads", cfg.UploadDir)

	// 组装 handler。
	authH := handler.NewAuthHandler(newAuthSvc(db, cfg))
	storyH := handler.NewStoryHandler(newStorySvc(db))
	userH := handler.NewUserHandler(newUserSvc(db))

	api := r.Group("/api")

	// 无需登录。
	api.GET("/ping", func(c *gin.Context) {
		c.JSON(200, gin.H{"code": 0, "msg": "pong"})
	})
	api.POST("/auth/register", authH.Register)
	api.POST("/auth/login", authH.Login)
	api.GET("/stories", storyH.List)
	api.GET("/stories/:id", storyH.Detail)
	api.POST("/upload", handler.Upload) // 简化：上传不强制登录，便于演示

	// 需要登录。
	authed := api.Group("")
	authed.Use(middleware.Auth(cfg))
	{
		authed.GET("/user/profile", userH.Profile)
		authed.PUT("/user/profile", userH.Update)

		authed.POST("/stories", storyH.Create)
		authed.POST("/stories/:id/append", storyH.AppendReward)
		authed.POST("/stories/:id/respond", storyH.Respond)
		authed.POST("/stories/:id/accept/:rid", storyH.Accept)
	}

	return r
}

package router

import (
	"memorylink/internal/config"
	"memorylink/internal/service"

	"gorm.io/gorm"
)

// 依赖装配的薄封装，集中在一处构造 service。
func newAuthSvc(db *gorm.DB, cfg *config.Config) *service.AuthService {
	return service.NewAuthService(db, cfg)
}
func newStorySvc(db *gorm.DB) *service.StoryService {
	return service.NewStoryService(db)
}
func newUserSvc(db *gorm.DB) *service.UserService {
	return service.NewUserService(db)
}

package main

import (
	"log"
	"os"

	"memorylink/internal/config"
	"memorylink/internal/db"
	"memorylink/internal/router"
)

func main() {
	cfg := config.Load()

	// 确保上传目录存在。
	if err := os.MkdirAll(cfg.UploadDir, 0o755); err != nil {
		log.Fatalf("创建上传目录失败: %v", err)
	}

	db.Init(cfg)
	r := router.Setup(db.DB, cfg)

	log.Printf("记忆连接后端启动: http://localhost:%s", cfg.ServerPort)
	if err := r.Run(":" + cfg.ServerPort); err != nil {
		log.Fatalf("服务启动失败: %v", err)
	}
}

