import axios from 'axios'
import { auth } from '../store/auth'
import router from '../router'

const request = axios.create({ baseURL: '/api', timeout: 10000 })

// 请求自动带上 token。
request.interceptors.request.use((config) => {
  if (auth.token) config.headers.Authorization = `Bearer ${auth.token}`
  return config
})

// 统一解包 { code, msg, data }，401 时清登录态并跳转。
request.interceptors.response.use(
  (resp) => {
    const body = resp.data
    if (body && typeof body === 'object' && 'code' in body) {
      if (body.code === 0) return body.data
      return Promise.reject(new Error(body.msg || '请求失败'))
    }
    return body
  },
  (error) => {
    const status = error.response?.status
    const msg = error.response?.data?.msg || error.message || '网络错误'
    if (status === 401) {
      auth.logout()
      if (router.currentRoute.value.name !== 'login') {
        router.push({ name: 'login' })
      }
    }
    return Promise.reject(new Error(msg))
  }
)

export default request

import request from './request'

export const authApi = {
  register: (data) => request.post('/auth/register', data),
  login: (data) => request.post('/auth/login', data)
}

export const storyApi = {
  list: (params) => request.get('/stories', { params }),
  detail: (id) => request.get(`/stories/${id}`),
  create: (data) => request.post('/stories', data),
  append: (id, add) => request.post(`/stories/${id}/append`, { add }),
  respond: (id, data) => request.post(`/stories/${id}/respond`, data),
  accept: (id, rid) => request.post(`/stories/${id}/accept/${rid}`)
}

export const userApi = {
  profile: () => request.get('/user/profile'),
  update: (data) => request.put('/user/profile', data)
}

export const uploadUrl = '/api/upload'

import { reactive, watch } from 'vue'

// 轻量全局登录态：token + 用户信息，持久化到 localStorage。
const stored = JSON.parse(localStorage.getItem('ml_auth') || 'null')

export const auth = reactive({
  token: stored?.token || '',
  user: stored?.user || null,
  get isLogin() {
    return !!this.token
  },
  setSession(token, user) {
    this.token = token
    this.user = user
  },
  logout() {
    this.token = ''
    this.user = null
  }
})

watch(
  () => [auth.token, auth.user],
  () => {
    if (auth.token) {
      localStorage.setItem('ml_auth', JSON.stringify({ token: auth.token, user: auth.user }))
    } else {
      localStorage.removeItem('ml_auth')
    }
  },
  { deep: true }
)

