:root {
  --paper: #f6efe3;
  --paper-2: #fffaf1;
  --ink: #43342a;
  --ink-soft: #8a7563;
  --amber: #c4783a;
  --amber-dark: #a45f28;
  --teal: #4a8583;
  --line: #e3d4bd;
  --shadow: 0 10px 30px rgba(98, 70, 40, 0.14);
  --radius: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body,
#app {
  min-height: 100%;
}

body {
  font-family: 'PingFang SC', 'Microsoft YaHei', 'Hiragino Sans GB', system-ui, sans-serif;
  color: var(--ink);
  background:
    radial-gradient(1200px 500px at 80% -10%, rgba(196, 120, 58, 0.12), transparent),
    radial-gradient(900px 500px at -10% 10%, rgba(74, 133, 131, 0.1), transparent),
    var(--paper);
  line-height: 1.6;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  outline: none;
}

img {
  display: block;
  max-width: 100%;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 18px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  background: var(--amber);
  color: #fff;
  transition: transform 0.15s, background 0.15s, opacity 0.15s;
}
.btn:hover {
  background: var(--amber-dark);
  transform: translateY(-1px);
}
.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}
.btn.ghost {
  background: transparent;
  color: var(--amber-dark);
  border: 1.5px solid var(--amber);
}
.btn.ghost:hover {
  background: rgba(196, 120, 58, 0.08);
}
.btn.teal {
  background: var(--teal);
}
.btn.teal:hover {
  background: #3a6d6b;
}
.btn.block {
  width: 100%;
}
.btn.sm {
  padding: 6px 14px;
  font-size: 13px;
}

.input,
.textarea,
.select {
  width: 100%;
  padding: 11px 14px;
  border: 1.5px solid var(--line);
  border-radius: 10px;
  background: var(--paper-2);
  color: var(--ink);
  font-size: 14px;
  font-family: inherit;
  transition: border-color 0.15s;
}
.input:focus,
.textarea:focus,
.select:focus {
  border-color: var(--amber);
  outline: none;
}
.textarea {
  resize: vertical;
  min-height: 84px;
}

.tag {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
}
.tag.open {
  background: rgba(74, 133, 131, 0.14);
  color: var(--teal);
}
.tag.completed {
  background: rgba(138, 117, 99, 0.18);
  color: var(--ink-soft);
}

.coin {
  color: var(--amber-dark);
  font-weight: 700;
}

.empty {
  text-align: center;
  color: var(--ink-soft);
  padding: 60px 20px;
}
.empty .big {
  font-size: 40px;
  margin-bottom: 10px;
}

/* 弹窗 */
.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(67, 52, 42, 0.45);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 40px 16px;
  z-index: 100;
  overflow-y: auto;
}
.modal {
  background: var(--paper-2);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  width: 100%;
  max-width: 520px;
  padding: 24px;
  animation: pop 0.2s ease;
}
@keyframes pop {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
}
.modal h3 {
  margin-bottom: 18px;
  font-size: 19px;
}
.field {
  margin-bottom: 14px;
}
.field label {
  display: block;
  font-size: 13px;
  color: var(--ink-soft);
  margin-bottom: 6px;
  font-weight: 600;
}
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
}

/* 轻提示 */
.toast {
  position: fixed;
  top: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 10px 22px;
  border-radius: 999px;
  font-size: 14px;
  z-index: 200;
  box-shadow: var(--shadow);
  animation: pop 0.2s ease;
}
.toast.err {
  background: #b4452f;
}

