func main() {
	cfg := config.Load()
	if err := os.MkdirAll(filepath.Join(cfg.UploadDir, "demo"), 0o755); err != nil {
		log.Fatal(err)
	}
	db.Init(cfg)
	gormDB := db.DB

	// 1) 清空旧数据，保证可重复执行、账目自洽。
	if err := reset(gormDB); err != nil {
		log.Fatalf("清空数据失败: %v", err)
	}
	// 2) 生成演示图片。
	old1 := saveImg(gradient(800, 560, [3]int{120, 88, 55}, [3]int{200, 170, 120}), "old_school.png")
	old2 := saveImg(gradient(800, 560, [3]int{90, 80, 60}, [3]int{170, 150, 110}), "old_alley.png")
	new1 := saveImg(gradient(800, 560, [3]int{74, 133, 131}, [3]int{180, 215, 205}), "new_school.png")
	new2 := saveImg(gradient(800, 560, [3]int{90, 150, 120}, [3]int{200, 225, 180}), "new_alley.png")
	cover := saveImg(gradient(800, 560, [3]int{196, 120, 58}, [3]int{230, 190, 140}), "new_station.png")

	authSvc := service.NewAuthService(gormDB, cfg)
	storySvc := service.NewStoryService(gormDB)

	mustReg := func(username, nick string) (string, uint) {
		u, token, err := authSvc.Register(username, "secret123", nick)
		if err != nil {
			log.Fatalf("注册 %s 失败: %v", username, err)
		}
		fmt.Printf("用户 %s(%s) 硬币=%d\n", nick, username, u.CoinBalance)
		return token, u.ID
	}

	// 用户：发起人阿篱、拍摄员小城、第三位离城青年阿川。
	aliceToken, _ := mustReg("alice", "阿篱")
	bobToken, _ := mustReg("bob", "小城拍摄员")
	chuanToken, _ := mustReg("chuan", "阿川")

	// 故事一：已完成的重逢（老校门）。
	s1, err := storySvc.CreateStory(1, service.CreateStoryInput{
		Title:      "再看一眼城南中学的老校门",
		Location:   "云岭市·城南中学",
		MemoryText: "高三那年每天骑车冲过这个校门，\n门口两排梧桐树把夏天的太阳剪成碎金子。\n毕业十年了，想知道它现在的样子。",
		OldPhotos:  model.StringSlice{old1, old2},
		Reward:     30,
	})
	if err != nil {
		log.Fatal(err)
	}
	if _, err := storySvc.AppendReward(1, s1.ID, 20); err != nil {
		log.Fatal(err)
	}
	r1, err := storySvc.AddResponse(2, s1.ID, new1,
		"我今天刚好路过！梧桐树都还在，比以前更粗了，校门重新刷成了墨绿色。")
	if err != nil {
		log.Fatal(err)
	}
	// 另一条未被采纳的现场。
	if _, err := storySvc.AddResponse(3, s1.ID, new2,
		"上周也去了一张，旁边多了家奶茶店，放学还是一样热闹。"); err != nil {
		log.Fatal(err)
	}
	if _, err := storySvc.AcceptResponse(1, s1.ID, r1.ID); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("故事《%s》已采纳结算，悬赏50 -> 小城拍摄员\n", s1.Title)

	// 故事二：求看中（老火车站）。
	s2, err := storySvc.CreateStory(3, service.CreateStoryInput{
		Title:      "帮我看看废弃的北站还在不在",
		Location:   "云岭市·老火车北站",
		MemoryText: "小时候爸爸在这里接我过暑假，\n绿皮火车的汽笛声特别响。听说要拆了，心里空落落的。",
		OldPhotos:  model.StringSlice{old2},
		Reward:     40,
	})
	if err != nil {
		log.Fatal(err)
	}
	if _, err := storySvc.AddResponse(2, s2.ID, cover,
		"主体还留着，围了围挡写着‘文创园改造中’，钟楼上的钟停在三点十七分。"); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("故事《%s》求看中，已有人去拍，等待阿川确认\n", s2.Title)

	// 故事三：求看中、尚无回应（巷子口的糖水铺）。
	if _, err := storySvc.CreateStory(1, service.CreateStoryInput{
		Title:      "巷口那家阿婆糖水铺还开着吗",
		Location:   "云岭市·西门老街 17 号",
		MemoryText: "五毛钱一碗的绿豆沙，阿婆总多给我半勺。\n离开小城后再也没喝过那个味道。",
		OldPhotos:  model.StringSlice{old1},
		Reward:     15,
	}); err != nil {
		log.Fatal(err)
	}

	fmt.Println("\n✅ 演示数据就绪。登录密码均为 secret123")
	fmt.Println("   alice=阿篱(发起人)  bob=小城拍摄员(拍摄者)  chuan=阿川(发起人)")
	_ = aliceToken
	_ = bobToken
	_ = chuanToken
}

